/* Site-admin only. Archives never enter localStorage or a public URL. */
let backupInfo=null,backupDownloading=false;
function backupsView(){
  const d=backupInfo;
  return `<article class="card backup-section"><h2>نسخة آمنة إلى جهازك</h2><p>تُنزل البيانات في ملف مشفّر بكلمة مرور تختارها. الموقع لا يحتفظ بالملف بعد التنزيل؛ احفظه في مكان آمن منفصل، واحفظ كلمة مروره في مدير كلمات المرور. فقدانها يمنع فتح النسخة.</p><p><strong>هذا تنزيل يدوي، وليس تخزينًا خارجيًا تلقائيًا.</strong> نسخ Render والتعافي الزمني مستقلة عنه. الملفات الخارجية وروابط الصور ورسائل وأعضاء Discord وإعدادات Render ليست ضمن هذا الملف.</p>${!d?'<p role="status">جارٍ تحميل نطاقات النسخ…</p>':`<form id="backupForm"><label>محتوى النسخة<select name="scope" id="backupScope"><option value="full">كاملة — جميع جداول الموقع</option>${d.groups.map(g=>`<option value="${safe(g.id)}">${safe(g.label)}</option>`).join('')}</select></label><details><summary>الجداول التي ستدخل في النسخة</summary><p id="backupTables" style="overflow-wrap:anywhere;direction:ltr;text-align:left"></p><p>تضاف الجداول التي تعتمد عليها البيانات تلقائيًا. النسخة المحددة لا تعوّض النسخة الكاملة للتعافي.</p></details><p>حد الملف المشفّر: 128 MiB. تُوقف العملية إذا تجاوزت الحدود؛ لا تُحفظ نسخة ناقصة.</p><label>كلمة مرور النسخة (16 حرفًا على الأقل)<input type="password" name="password" autocomplete="new-password" minlength="16" maxlength="256" required></label><label>تأكيد كلمة المرور<input type="password" name="confirmPassword" autocomplete="new-password" minlength="16" maxlength="256" required></label><label><input type="checkbox" style="width:auto" name="includeRecoveryKey" id="backupRecoveryKey"> تضمين مفتاح فك بيانات البوتات داخل الملف المشفّر (للنسخة الكاملة فقط)</label><p>بدون المفتاح تحتاج مفتاح الموقع الأصلي لفك بيانات البوتات بعد الاسترجاع. لا ترسل المفتاح أو كلمة مرور النسخة في المحادثات.</p><label><input type="checkbox" style="width:auto" name="acknowledge" required> أفهم أن النسخة تحتوي بيانات العملاء الحساسة، وسأحفظ الملف وكلمة مروره بأمان.</label><button class="btn primary" type="submit" ${backupDownloading?'disabled':''}>${backupDownloading?'جارٍ تجهيز النسخة…':'إنشاء وتنزيل نسخة مشفّرة'}</button><p id="backupStatus" role="status" aria-live="polite"></p></form>`}</article><article class="card backup-section"><h2>الاسترجاع والتعافي</h2><p>يُفحص الملف ثم يُسترجع في قاعدة فارغة منفصلة بأداة المشغّل. لا يوجد استبدال مباشر لقاعدة العملاء من هذه الصفحة. بعد الاسترجاع تُراجع الجداول والمفاتيح والمهام المعلّقة قبل تشغيل البوتات لتجنب تكرار التنفيذ.</p><a class="btn" href="https://dashboard.render.com/d/dpg-dan4jcrtqb8s73aivb20-a/recovery" target="_blank" rel="noopener noreferrer">نسخ Render والتعافي الزمني ↗</a></article><article class="card backup-section"><h2>سجل النسخ</h2><p>«أُرسل الملف» يعني اكتمال إرساله من الموقع، ولا يثبت حفظه على جهازك أو اختبار استرجاعه. أكّد وجوده في التنزيلات.</p>${d?table(['التاريخ','العملية','الحجم'],d.history.map(r=>`<tr><td>${safe(new Date(r.created_at).toLocaleString('ar-SA'))}</td><td>${safe({'admin.backup.started':'بدأ التجهيز','admin.backup.prepared':'اكتمل تجهيز الملف','admin.backup.sent':'أُرسل الملف','admin.backup.failed':'لم تكتمل العملية','admin.backup.drill':'نجح استرجاع منفصل وفحص البيانات'}[r.action]||r.action)}</td><td>${r.details?.bytes?safe((r.details.bytes/1048576).toFixed(2))+' MiB':'—'}</td></tr>`).join('')):'—'}</article>`;
}
async function refreshBackups(){backupInfo=await api('/api/admin/backups');if(view==='backups')render();}
function bindBackups(){
  const form=document.querySelector('#backupForm');if(!form)return;
  const scope=form.elements.scope,tables=document.querySelector('#backupTables'),key=form.elements.includeRecoveryKey;
  const update=()=>{tables.textContent=(scope.value==='full'?backupInfo.tables:backupInfo.groups.find(g=>g.id===scope.value)?.tables||[]).join(' · ');key.disabled=scope.value!=='full';if(key.disabled)key.checked=false;};scope.onchange=update;update();
  form.onsubmit=async event=>{
    event.preventDefault();if(backupDownloading)return;
    if(form.elements.password.value!==form.elements.confirmPassword.value){error(new Error('كلمتا المرور غير متطابقتين.'));return;}
    backupDownloading=true;const button=form.querySelector('button[type=submit]'),status=document.querySelector('#backupStatus');button.disabled=true;button.textContent='جارٍ تجهيز النسخة…';status.textContent='ابقَ في الصفحة حتى يبدأ التنزيل. قد تستغرق العملية حتى دقيقتين.';
    try{
      const response=await fetch('/api/admin/backups/download',{method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':await csrf()},body:JSON.stringify({scope:scope.value,password:form.elements.password.value,confirmPassword:form.elements.confirmPassword.value,includeRecoveryKey:key.checked,acknowledge:form.elements.acknowledge.checked})});
      if(!response.ok){const body=await response.json();const e=new Error(body.error||'تعذر التنزيل.');e.reauthUrl=body.reauthUrl;throw e;}
      const blob=await response.blob();if(blob.size<52 || blob.size>128*1048576)throw new Error('حجم ملف النسخة غير صالح.');
      const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=response.headers.get('Content-Disposition')?.match(/filename="([a-zA-Z0-9_.-]+)"/)?.[1]||'diskoko-backup.dkbackup';a.click();setTimeout(()=>URL.revokeObjectURL(url),60_000);
      status.textContent='بدأ تنزيل الملف المشفّر. تحقق من حفظه على جهازك، ثم احفظ كلمة مروره في مكان منفصل.';form.elements.password.value='';form.elements.confirmPassword.value='';toast('جهزت النسخة المشفّرة للتنزيل');
    }catch(e){status.textContent='لم يكتمل التنزيل. لم تتغير بيانات الموقع.';error(e);}
    finally{backupDownloading=false;const live=document.querySelector('#backupForm button[type=submit]');if(live){live.disabled=false;live.textContent='إنشاء وتنزيل نسخة مشفّرة';}}
  };
}
